package fr.acinq.secp256k1

import kotlinx.serialization.json.*
import kotlin.test.*

/**
 * Reduced-enrollment regression vectors generated by the pinned submodule's independent Python
 * implementation. These are not published interoperability vectors: they pin the wrapper's argument
 * order, session binding, triangular matrix conventions and marshalling against frozen answers.
 */
@OptIn(ExperimentalUnsignedTypes::class)
class FrostEnrollmentVectorsTest {
    private fun JsonElement.hex(name: String): ByteArray = Hex.decode(jsonObject[name]!!.jsonPrimitive.content)
    private fun JsonElement.int(name: String): Int = jsonObject[name]!!.jsonPrimitive.int
    private fun JsonElement.text(name: String): String = jsonObject[name]!!.jsonPrimitive.content
    private fun JsonElement.ids(name: String): UIntArray = jsonObject[name]!!.jsonArray.map { it.jsonPrimitive.int.toUInt() }.toUIntArray()
    private fun JsonElement.strs(name: String): List<ByteArray> = jsonObject[name]!!.jsonArray.map { Hex.decode(it.jsonPrimitive.content) }
    private fun JsonElement.rows(name: String): List<Array<ByteArray>> = jsonObject[name]!!.jsonArray.map { row ->
        row.jsonArray.map { Hex.decode(it.jsonPrimitive.content) }.toTypedArray()
    }

    @Test
    fun reducedEnrollmentVectors() {
        val tests = readResourceAsJson("frost/enrollment_reduced_vectors.json")
        assertEquals("a04dc1edd71783990e1fcde648fa42ac5d03eefa", tests.text("source_commit"))
        assertEquals("regression", tests.text("kind"))
        var count = 0
        tests.jsonObject["cases"]!!.jsonArray.forEach { v ->
            val label = "tc${v.int("tc_id")}"
            val n = v.int("n_participants")
            val t = v.int("threshold")
            val ids = v.ids("ids")
            val newId = v.int("new_id").toUInt()
            val threshPk = v.hex("thresh_pk")
            val pubshares = v.strs("pubshares").toTypedArray()
            val secshares = v.strs("secshares")
            val sessionId = v.hex("session_id")
            val secrands = v.strs("session_secrand")
            val expectedHash = v.hex("params_hash")
            val expectedShares = v.rows("shares")
            val expectedSigmas = v.strs("sigmas")

            assertContentEquals(expectedHash, Secp256k1.frostEnrollmentReducedParamsHash(threshPk, ids, newId, n, t, sessionId), label)
            val round1 = ids.mapIndexed { i, myId ->
                val out = Secp256k1.frostEnrollmentReducedSharesGen(secrands[i], secshares[i], threshPk, ids, myId, newId, n, t, sessionId)
                assertContentEquals(expectedHash, out.second, "$label helper $myId hash")
                expectedShares[i].forEachIndexed { j, expected ->
                    assertContentEquals(expected, out.first[j], "$label helper $myId cell ${ids[j]}")
                }
                out
            }
            round1.forEachIndexed { i, source ->
                ids.forEachIndexed { j, recipient ->
                    if (recipient < ids[i]) assertContentEquals(ByteArray(32), source.first[j], "$label omitted ${ids[i]} -> $recipient")
                }
            }

            val sigmas = ids.mapIndexed { j, myId ->
                val allShares = Array(ids.size) { i -> round1[i].first[j] }
                val hashes = Array(ids.size) { i -> if (ids[i] < myId) round1[i].second else ByteArray(32) }
                val result = Secp256k1.frostEnrollmentReducedShareAgg(allShares, hashes, threshPk, ids, myId, newId, n, t, sessionId)
                assertTrue(result.isOk, "$label aggregation failed for $myId")
                assertNull(result.mismatchId)
                assertContentEquals(expectedSigmas[j], result.sigma, "$label sigma $myId")
                result.sigma!!
            }.toTypedArray()

            val expectedPubshare = v.hex("new_pubshare")
            val newPubshare = Secp256k1.frostEnrollmentPubshareDerive(pubshares, ids, newId, n, t)
            assertContentEquals(expectedPubshare, Secp256k1.pubKeyCompress(newPubshare), "$label public share")
            val hashes = round1.map { it.second }.toTypedArray()
            val newSecshare = Secp256k1.frostEnrollmentReducedSecshareGen(sigmas, hashes, threshPk, ids, newId, n, t, sessionId, newPubshare)
            assertContentEquals(v.hex("new_secshare"), newSecshare, "$label secret share")
            count++
        }
        assertEquals(4, count)
    }
}
